from fractions import Fraction

M = 2025

def calculate_S(N, M):
    # First Summation: A = sum_{n=1}^{N} M^n / product_{k=1}^{n} (k+M)
    Sum_A = Fraction(0)
    for n in range(1, N + 1):
        numerator = Fraction(M**n)
        denominator = 1
        for k in range(1, n + 1):
            denominator *= (k + M)

        Sum_A += numerator / denominator

    # Second Summation: B = sum_{n=1}^{N} product_{k=1}^{n} (1 - k/M)
    Sum_B = Fraction(0)
    for n in range(1, N + 1):
        prod_B_n = 1
        for k in range(1, n + 1):
            prod_B_n *= (1 - k / M)

        Sum_B += prod_B_n

    return Sum_A - Sum_B

# Calculate for N = 3, 4, 5
results = {}
for N in [3, 4, 5]:
    results[N] = calculate_S(N, M)

for N, result in results.items():
    print(f"N={N}: Exact Fraction = {result}, Floor = {int(result)}")
